"""Редакторская и смысловая сверка пакета OMS после build_package.py."""
import csv
import hashlib
import json
from pathlib import Path

R=Path(__file__).resolve().parent
def get(p):return json.loads((R/p).read_text())
def put(p,x):(R/p).write_text(json.dumps(x,ensure_ascii=False,indent=2,allow_nan=False)+'\n')
def rows(p):
    with (R/p).open(newline='') as f:return list(csv.DictReader(f))
def table(p,x):
    with (R/p).open('w',newline='') as f:
        w=csv.DictWriter(f,fieldnames=list(x[0]));w.writeheader();w.writerows(x)
def h(p):return hashlib.sha256(p.read_bytes()).hexdigest()

